INSERT INTO `genres` (`id`, `name`, `slug`, `description`, `created_at`, `updated_at`) VALUES (1,'Action','action','Fast paced stories with intense battles and high stakes.','2026-08-14 13:17:46','2026-08-14 13:17:46'),(2,'Adventure','adventure','Exploration, quests, and journeys into unknown worlds.','2026-08-14 13:17:46','2026-08-14 13:17:46'),(3,'Fantasy','fantasy','Magic, mythic worlds, and legendary creatures.','2026-08-14 13:17:46','2026-08-14 13:17:46'),(4,'Horror','horror','Dark atmospheres, dread, and terrifying encounters.','2026-08-14 13:17:46','2026-08-14 13:17:46'),(5,'Romance','romance','Emotional connections and relationship-driven stories.','2026-08-14 13:17:46','2026-08-14 13:17:46'),(6,'Comedy','comedy','Lighthearted stories meant to entertain and amuse.','2026-08-14 13:17:46','2026-08-14 13:17:46'),(7,'Sci-Fi','sci-fi','Explores futuristic technology, artificial intelligence, space travel, time travel, or post-apocalyptic/dystopian societies.','2026-08-25 03:01:33','2026-08-25 03:01:33'),(8,'Mystery & Detective','mystery-detective','Built around puzzles, crime-solving, and deep investigations that challenge the reader to guess the culprit or uncover hidden secrets.','2026-08-25 03:02:38','2026-08-25 03:02:38'),(9,'Slice of Life','slice-of-life','Portrays realistic, everyday experiences—such as school life, workplace dynamics, or family relationships—without grand or overly dramatic conflicts.','2026-08-25 03:03:48','2026-08-25 03:03:48'),(10,'Thriller','thriller','Focuses on creating psychological tension, anxiety, and adrenaline-pumping suspense. Unlike Mystery (which centers on solving a puzzle or finding a culprit), a Thriller revolves around survival, high-stakes conflict, mental games, and escaping imminent danger.','2026-08-25 03:06:08','2026-08-25 03:06:08');
INSERT INTO `comics` (`id`, `external_provider`, `external_id`, `source_url`, `title`, `slug`, `description`, `author`, `publisher`, `original_published_at`, `cover_image`, `status`, `published_at`, `is_featured`, `seo_title`, `seo_description`, `source_metadata`, `created_at`, `updated_at`) VALUES (1,NULL,NULL,NULL,'Trees','Trees-Volume-1','Trees (Volume 1 / Issue 1) karya Warren Ellis dan ilustrator Jason Howard, diterbitkan oleh Image Comics.\r\n​Kisah berlatar sepuluh tahun setelah invasi alien misterius di mana struktur raksasa berbentuk tiang (\"Trees\") mendarat di berbagai kota besar di seluruh Bumi. Uniknya, alien tersebut tidak pernah mencoba berkomunikasi, menginvasi secara aktif, ataupun mempedulikan keberadaan manusia. Kehadiran pasif namun masif ini mengubah kondisi sosial, budaya, dan politik dunia secara drastis. Issue pertama ini membuka cerita dengan memperkenalkan dampaknya di berbagai penjuru dunia—mulai dari kota eksperimen budaya Shu di Tiongkok hingga ketegangan politik dan investigasi ilmiah di sekitar area struktur misterius tersebut.',NULL,NULL,NULL,'comics/covers/media_1787607866_8f627153.jpeg','ongoing','2025-08-07 17:00:00',1,'Trees Vol 1 / Issue 1 – Sinopsis Komik Sci-Fi & Review','Baca deskripsi Trees Issue 1 karya Warren Ellis & Jason Howard. Awal mula kedatangan alien raksasa misterius di Bumi dalam komik sci-fi Image Comics!',NULL,'2026-08-14 13:17:46','2026-08-26 12:08:59'),(2,NULL,NULL,NULL,'Bloodborne','Blood-borne','Bloodborne (diterbitkan oleh Titan Comics) adalah adaptasi komik horor Gotik dan Lovecraftian berdasarkan video game legendaris karya FromSoftware dan Sony Interactive Entertainment. Komik ini ditulis oleh Ales Kot dan diilustrasikan oleh Piotr Kowalski (dengan sampul oleh Jeff Stokley).\r\n​Kisah ini berlatar di kota kuno Yharnam yang terkutuk dan dilanda wabah penyakit darah mengerikan yang mengubah warganya menjadi monster buas. Seorang Hunter (Pemburu) terbangun di tengah malam perburuan tak berujung (\"The Hunt\") dan harus membantai monster-monster mengerikan demi bertahan hidup. Di tengah kegilaan dan tumpah darah, sang Pemburu berjuang mencari jalan keluar dari siklus penderitaan ini serta mengungkap misteri rahasia Paleblood yang tersembunyi di balik kegelapan kota.',NULL,NULL,NULL,'comics/covers/media_1787621337_b57fb0aa.jpeg','ongoing','2025-11-09 17:00:00',0,'Bloodborne Comic – Sinopsis Komik Horor Titan Comics & Review','Baca deskripsi komik Bloodborne karya Ales Kot & Piotr Kowalski dari Titan Comics. Jelajahi kota Yharnam yang terkutuk dan pertarungan sang Hunter!',NULL,'2026-08-14 13:17:46','2026-08-24 18:28:57'),(3,NULL,NULL,NULL,'Sons of The Devil','Sons-of-The-Devil','Sons of the Devil (Issue One) adalah komik horor psikologis karya penulis Brian Buccellato dan ilustrator Toni Infante, diterbitkan oleh Image Comics.\r\n​Kisah ini menceritakan tentang Travis, seorang pemuda temperamental yang dibesarkan di panti asuhan dan memiliki masa lalu yang kelam. Kehidupannya yang biasa mulai hancur ketika sebuah investigasi menemukan rahasia mengerikan di balik asal-usul keluarganya. Travis terhubung secara langsung dengan sebuah sekte keagamaan ekstrem (cult) dan pemimpinnya yang berdarah dingin dari era 1980-an. Komik ini menggabungkan elemen thriller kejahatan dan horor gaib yang mencekam saat Travis berusaha mengungkap kebenaran di balik warisan darah keluarganya.',NULL,NULL,NULL,'comics/covers/media_1787517537_aa01bdac.jpeg','ongoing','2024-12-31 17:00:00',1,'Sons of the Devil Issue 1 – Sinopsis Komik Horor & Review','Baca deskripsi Sons of the Devil Issue 1 karya Brian Buccellato. Temukan misteri sekte sesat, horor psikologis, dan rahasia kelam masa lalu Travis!',NULL,'2026-08-14 13:17:46','2026-08-26 12:04:32'),(4,NULL,NULL,NULL,'NailBiter: The Munder Edition','NailBiter-The-Munder-Edition','Nailbiter: The Murder Edition Vol. 1 adalah komik horor-thriller psikologis karya penulis Joshua Williamson dan ilustrator Mike Henderson, diterbitkan oleh Image Comics.\r\n​Kisah ini berpusat di kota kecil Buckaroo, Oregon, yang menyimpan rahasia mengerikan: kota ini merupakan tempat kelahiran 16 pembunuh berantai paling kejam di Amerika Serikat. Salah satu yang paling terkenal adalah Edward Charles Warren, sang \"Nailbiter,\" yang memiliki kebiasaan mengunyah kuku korbannya sampai ke tulang. Ketika seorang agen FBI menghilang saat menyelidiki alasan di balik fenomena aneh kota tersebut, rekannya, Nicholas Finch, harus bekerja sama dengan sang Nailbiter sendiri untuk mengungkap konspirasi gelap di balik rahasia mengerikan kota Buckaroo.',NULL,NULL,NULL,'comics/covers/media_1787624042_fc55fec1.jpeg','ongoing','2025-04-14 17:00:00',0,'Nailbiter Vol 1: The Murder Edition – Sinopsis Komik Thriller & Review','Baca deskripsi Nailbiter Vol 1 karya Joshua Williamson. Misteri kota kelahiran 16 pembunuh berantai dalam komik horor psikologis Image Comics!',NULL,'2026-08-23 13:22:43','2026-08-24 19:14:02'),(5,NULL,NULL,NULL,'The Weather Man','The-Weather-Man','The Weatherman #1 adalah komik fiksi ilmiah penuh aksi dan humor gelap karya penulis Jody LeHeup, ilustrator Nathan Fox, serta pewarna Dave Stewart, diterbitkan oleh Image Comics.\r\n\r\nKisah ini berlatar di masa depan di mana Planet Mars telah dihuni manusia setelah Bumi hancur akibat serangan teroris dahsyat yang menewaskan miliaran jiwa. Nathan Bright adalah seorang pembawa acara cuaca (weatherman) yang populer, konyol, dan disukai banyak orang di Mars. Namun, kehidupannya yang santai mendadak hancur ketika ia dituduh sebagai dalang teroris utama di balik kehancuran Bumi. Masalahnya, ingatan Nathan telah dihapus sepenuhnya, sehingga ia tidak tahu apakah ia benar-benar monster pembunuh massal atau sekadar korban jebakan. Nathan kini harus kabur dari kejaran agen rahasia dan pemburu bayaran sambil berusaha memulihkan ingatannya demi mencegah serangan berikutnya.','Jody Leheup','Image Comics','2018-06-09','comics/covers/media_1787773794_e635c1ba.jpeg','completed','2018-06-08 17:00:00',0,'The Weatherman #1 – Sinopsis Komik Sci-Fi Action & Review','Baca deskripsi The Weatherman #1 karya Jody LeHeup & Nathan Fox. Kisah pembawa acara cuaca di Mars yang dituduh memusnahkan Bumi dalam komik Image Comics!',NULL,'2026-08-26 12:49:54','2026-09-01 13:37:38'),(9,'google_books','6uGcDwAAQBAJ','https://play.google.com/store/books/details?id=6uGcDwAAQBAJ','The Weatherman Vol. 2 #1','the-weatherman-vol-2-1','Nathan Bright has no memory of his alleged role in the terrorist attack that killed 18 billion people, but that isn\'t stopping him from trying to atone for the actions of his past self. Hunted by literally everyone in the galaxy, Nathan\'s quest for redemption takes him to the scene of the crime where he discovers that Earth\'s not lifeless at allÉ it\'s monstrous! This summer, writer JODY LEHEUP (SHIRTLESS BEAR_-FIGHTER!), artist NATHAN FOX (HAUNT, DMZ), and colorist MORENO DINISIO (BLACK SCIENCE) return with the hotly anticipated second chapter of their jaw-dropping, critically acclaimed sci-fi sensation!','Jody Leheup','Image Comics','2019-06-26','comics/covers/import_google_books_6uGcDwAAQBAJ_d54b56a1.jpg','completed','2019-06-25 17:00:00',0,'The Weatherman Vol. 2 #1','Nathan Bright has no memory of his alleged role in the terrorist attack that killed 18 billion people, but that isn\'t stopping him from trying to atone for the actions of his past self. Hunted by literally everyone in the galaxy, Nathan\'s quest for redemption takes him to the scene of the crime where he discovers that Earth\'s not lifeless at allÉ it\'s monstrous! This summer, writer JODY LEHEUP (SHIRTLESS BEAR_-FIGHTER!), artist NATHAN FOX (HAUNT, DMZ), and colorist MORENO DINISIO (BLACK SCIENCE)','{\"genres\":[\"Comics & Graphic Novels \\/ Science Fiction \\/ General\"],\"cover_url\":\"https:\\/\\/books.google.com\\/books\\/publisher\\/content?id=6uGcDwAAQBAJ&printsec=frontcover&img=1&zoom=6&edge=curl&imgtk=AFLRE71A-J27mtRveqRBHLfDvL2b-XHhdQfwNCcBL3x295L_Zfjn7qZjmHz1262rurEFlJCKhVT7o9ZH_vKumwYq5y4CoLUA5OlwZ0ef8Orsa6uKhn7FJ7fmmS4oTIu2R1AxD2fkTphy&source=gbs_api\",\"imported_at\":\"2026-09-01T20:12:25+00:00\"}','2026-09-01 13:12:25','2026-09-01 13:14:54'),(10,'google_books','MXbxEAAAQBAJ','https://play.google.com/store/books/details?id=MXbxEAAAQBAJ','The Weatherman #2','the-weatherman-2','Nathan must pass a loyalty test in order to gain an audience with the leader of the Sword of God. Cross has a falling out with the Arcadian President. Fears of a world-ending attack on Mars mount as the clock ticks...','Jody LeHeup','Image Comics','2024-02-14','comics/covers/import_google_books_MXbxEAAAQBAJ_095e7d1d.jpg','completed','2024-02-13 17:00:00',0,'The Weatherman #2','Nathan must pass a loyalty test in order to gain an audience with the leader of the Sword of God. Cross has a falling out with the Arcadian President. Fears of a world-ending attack on Mars mount as the clock ticks...','{\"genres\":[\"Comics & Graphic Novels \\/ Science Fiction \\/ General\"],\"cover_url\":\"https:\\/\\/books.google.com\\/books\\/publisher\\/content?id=MXbxEAAAQBAJ&printsec=frontcover&img=1&zoom=6&edge=curl&imgtk=AFLRE72xC5HPA8bdr3Q_STKBCy8LJQPIm-pDvLZZQ7fCLgt3FHkEclOWR_yFWAy5wKSmLemmfWuqzrYv5XMQSd-PGzI4_DEHdt_YB1WKUj7zWETl3ZDckp0gCrGiIaDz-mHaRlRYsaKV&source=gbs_api\",\"preview\":{\"embeddable\":true,\"viewability\":\"PARTIAL\",\"access_view_status\":\"SAMPLE\",\"public_domain\":false,\"web_reader_url\":\"https:\\/\\/play.google.com\\/books\\/reader?id=MXbxEAAAQBAJ&hl=&source=gbs_api\",\"epub_available\":false,\"pdf_available\":true},\"imported_at\":\"2026-09-01T21:15:01+00:00\"}','2026-09-01 14:15:01','2026-09-01 14:15:39');
